    if (typeof value !== 'string' || !/^\d+$/.test(value)) {
      throw new Error('Inventory revision metadata is missing or invalid')
    }
    const revision = Number(value)
    if (!Number.isFinite(revision) || !Number.isSafeInteger(revision) || revision < 0) {
